      "description": "从同一批案例、访谈、新闻、数据、融资卡或已有素材中，先锁定决策者与具体决策，再挖出足够有判断力的关系，生成 10 个实质不同的文章选题并相互比较。支持投资者分析行业趋势、产业机会、赛道机会、收入与利润分配、投资回报和风险，也支持创业者分析赛道机会、竞争环境、产品竞争力、产品战略和市场变化。使用管理、市场、营销、人力资源、战略、行政和投资领域已有且易懂的专业概念，不生造抽象词。按“有用＞有利＞有趣”取舍，同时评估传播、共鸣、企业痛点和获客效果，并在老方确认前停止写作。用户要求选题、比较切入点、从投资者或创业者角度看材料、准备写文章或说先不要起草时使用。",
      "originalDescription": "从同一批案例、访谈、新闻、数据、融资卡或已有素材中，先锁定决策者与具体决策，再挖出足够有判断力的关系，生成 10 个实质不同的文章选题并相互比较。支持投资者分析行业趋势、产业机会、赛道机会、收入与利润分配、投资回报和风险，也支持创业者分析赛道机会、竞争环境、产品竞争力、产品战略和市场变化。使用管理、市场、营销、人力资源、战略、行政和投资领域已有且易懂的专业概念，不生造抽象词。按“有用＞有利＞有趣”取舍，同时评估传播、共鸣、企业痛点和获客效果，并在老方确认前停止写作。用户要求选题、比较切入点、从投资者或创业者角度看材料、准备写文章或说先不要起草时使用。",
